<?php
namespace local_tm_course;

defined('MOODLE_INTERNAL') || die();

/**
 * Email logo image bytes: prefer on-disk pix/email, fallback to embedded base64.
 *
 * Note: training_center_logo file is named .png but the binary is JPEG (JFIF).
 *
 * @package local_tm_course
 */
class email_logo_assets {

    /**
     * @return string|null Raw image bytes (PNG or JPEG)
     */
    public static function image_bytes(string $key): ?string {
        $disk = self::disk_path($key);
        if ($disk !== null && is_readable($disk)) {
            $raw = file_get_contents($disk);
            return ($raw === false || $raw === '') ? null : $raw;
        }
        $map = self::base64_map();
        if (!isset($map[$key])) {
            return null;
        }
        $bin = base64_decode($map[$key], true);
        return ($bin === false || $bin === '') ? null : $bin;
    }

    /** @deprecated Use image_bytes() */
    public static function png_bytes(string $key): ?string {
        return self::image_bytes($key);
    }

    /**
     * MIME type from magic bytes (do not trust filename extension).
     */
    public static function content_type(string $bytes): string {
        if (strncmp($bytes, "\x89PNG\r\n\x1a\n", 8) === 0) {
            return 'image/png';
        }
        if (strncmp($bytes, "\xff\xd8\xff", 3) === 0) {
            return 'image/jpeg';
        }
        if (strncmp($bytes, 'GIF87a', 6) === 0 || strncmp($bytes, 'GIF89a', 6) === 0) {
            return 'image/gif';
        }
        return 'application/octet-stream';
    }

    public static function filename(string $key): ?string {
        $names = [
            'tm_robot_logo' => 'tm_robot_logo.png',
            'training_center_logo' => 'training_center_logo.png',
        ];
        return $names[$key] ?? null;
    }

    public static function key_from_filename(string $filename): ?string {
        foreach (['tm_robot_logo' => 'tm_robot_logo.png', 'training_center_logo' => 'training_center_logo.png'] as $key => $name) {
            if ($name === $filename) {
                return $key;
            }
        }
        return null;
    }

    public static function disk_path(string $key): ?string {
        $filename = self::filename($key);
        if ($filename === null) {
            return null;
        }
        return dirname(__DIR__) . '/pix/email/' . $filename;
    }

    /**
     * @return array<string,string>
     */
    private static function base64_map(): array {
        return [            'tm_robot_logo' => '',
            'training_center_logo' => '',
        ];
    }
}